  return { resultados, operaciones };
}

function informeConPrefijos(tramos, consultas) {
  const prefijos = [0];
  for (const minutos of tramos) {
    prefijos.push(prefijos[prefijos.length - 1] + minutos);
  }
  const resultados = [];
  let operaciones = tramos.length;
  for (const consulta of consultas) {
    const inicio = consulta[0];
    const fin = consulta[1];
    if (intervaloValido(tramos, inicio, fin)) {
      resultados.push(prefijos[fin] - prefijos[inicio]);
      operaciones++;
    } else {
      resultados.push(null);
    }
  }
  return { resultados, operaciones, celdasExtra: prefijos.length };
}

function decidirEstrategia(tramos, consultas, presupuesto) {
  const directo = informeDirecto(tramos, consultas);
  const indice = informeConPrefijos(tramos, consultas);
  let coinciden = directo.resultados.length === indice.resultados.length;
  for (let i = 0; i < directo.resultados.length; i++) {
    if (directo.resultados[i] !== indice.resultados[i]) coinciden = false;
  }
  const usarIndice = coinciden
    && indice.operaciones < directo.operaciones;
  return {
    resultados: directo.resultados,
    coinciden,
    operacionesDirectas: directo.operaciones,
    operacionesIndice: indice.operaciones,
    celdasIndice: indice.celdasExtra,
    estrategia: usarIndice ? "prefijos" : "directa"
  };
}

